/**
 * Stream Handler
 *
 * Processes SSE events from the OpenAI Responses API,
 * updating the accumulator and stream store.
 */

import type { ToolCall } from '../types';
import type { StreamStore } from '../streaming/types';
import type { AgentCallbacks, StreamAccumulator } from './types';

/**
 * Context for stream event handling
 */
export interface StreamHandlerContext {
  streamStore: StreamStore;
  streamId: string;
  accumulator: StreamAccumulator;
  callbacks?: AgentCallbacks;
  agentId?: string;
  agentDepth?: number;
}

/**
 * Handle a single SSE event from the Responses API
 */
export async function handleStreamEvent(
  event: ResponsesAPIEvent,
  context: StreamHandlerContext
): Promise<void> {
  const { streamStore, streamId, accumulator, callbacks, agentId, agentDepth } = context;

  switch (event.type) {
    case 'response.output_item.added': {
      // New output item - check if it's a function call
      if (event.item?.type === 'function_call') {
        const item = event.item;
        const itemId = item.id || event.item_id || item.call_id;

        if (item.name) {
          const id = itemId || `output-${event.output_index}`;
          const existing = accumulator.toolCalls.find(tc => tc.id === id);

          if (!existing) {
            const toolCall: ToolCall = {
              id,
              type: 'function',
              function: { name: item.name, arguments: '' },
            };
            // Store internal fields for later
            (toolCall as any)._outputIndex = event.output_index;
            (toolCall as any)._callId = item.call_id;
            accumulator.toolCalls.push(toolCall);
          }
        }
      }
      break;
    }

    case 'response.output_text.delta': {
      // Text content delta
      const delta = event.delta || '';
      if (delta) {
        accumulator.content += delta;
        callbacks?.onToken?.(delta);

        await streamStore.append(streamId, {
          type: 'token',
          content: delta,
          timestamp: Date.now(),
          agentId,
          agentDepth,
        });
      }
      break;
    }

    case 'response.reasoning.delta':
    case 'response.reasoning_summary_text.delta': {
      // Reasoning delta
      const delta = event.delta || '';
      if (delta) {
        accumulator.reasoning += delta;
        callbacks?.onReasoning?.(delta);

        await streamStore.append(streamId, {
          type: 'reasoning',
          content: delta,
          timestamp: Date.now(),
          agentId,
          agentDepth,
        });
      }
      break;
    }

    case 'response.function_call_arguments.delta': {
      // Tool call arguments delta
      const callId = event.call_id || event.item_id;
      const delta = event.delta || '';

      let existing = accumulator.toolCalls.find(tc => tc.id === callId);
      if (!existing && event.output_index !== undefined) {
        existing = accumulator.toolCalls.find(
          tc => (tc as any)._outputIndex === event.output_index
        );
        if (existing && callId) {
          existing.id = callId;
        }
      }

      if (!existing) {
        existing = {
          id: callId || `output-${event.output_index}`,
          type: 'function',
          function: { name: event.name || '', arguments: '' },
        };
        (existing as any)._outputIndex = event.output_index;
        accumulator.toolCalls.push(existing);
      }

      if (event.name && !existing.function.name) {
        existing.function.name = event.name;
      }
      existing.function.arguments += delta;
      break;
    }

    case 'response.function_call_arguments.done': {
      // Tool call complete
      const callId = event.call_id || event.item_id;

      let existing = accumulator.toolCalls.find(tc => tc.id === callId);
      if (!existing && event.output_index !== undefined) {
        existing = accumulator.toolCalls.find(
          tc => (tc as any)._outputIndex === event.output_index
        );
      }

      if (!existing && (event.name || event.arguments)) {
        existing = {
          id: callId || `output-${event.output_index}`,
          type: 'function',
          function: { name: event.name || '', arguments: '' },
        };
        (existing as any)._outputIndex = event.output_index;
        accumulator.toolCalls.push(existing);
      }

      if (existing) {
        if (event.name && !existing.function.name) {
          existing.function.name = event.name;
        }
        // Use full arguments if provided and we don't have accumulated ones
        if (event.arguments) {
          if (!existing.function.arguments || existing.function.arguments === '{}') {
            existing.function.arguments = event.arguments;
          }
        }
      }
      break;
    }

    case 'response.completed': {
      // Get final token counts
      if (event.response?.usage) {
        accumulator.inputTokens = event.response.usage.input_tokens || 0;
        accumulator.outputTokens = event.response.usage.output_tokens || 0;
      }
      break;
    }

    default:
      // Ignore other event types
      break;
  }
}

/**
 * Responses API event types
 */
interface ResponsesAPIEvent {
  type: string;
  item?: {
    type?: string;
    id?: string;
    call_id?: string;
    name?: string;
  };
  item_id?: string;
  output_index?: number;
  delta?: string;
  call_id?: string;
  name?: string;
  arguments?: string;
  response?: {
    usage?: {
      input_tokens?: number;
      output_tokens?: number;
    };
  };
}
