/**
 * Convex Database Implementation
 *
 * Repository implementations using Convex as the backend.
 * Requires the Convex client to be set up in the consuming app.
 */

import type {
  Conversation,
  CreateConversation,
  DBMessage,
  CreateMessage,
  DBSession,
  CreateSession,
  ConversationRepository,
  MessageRepository,
  SessionRepository,
  Repositories,
} from './types';
import type { SessionStatus, ToolCall } from '../types';

/**
 * Convex client interface
 * The actual client is provided by the consuming app
 */
export interface ConvexClient {
  query<T>(name: string, args: Record<string, unknown>): Promise<T>;
  mutation<T>(name: string, args: Record<string, unknown>): Promise<T>;
  action<T>(name: string, args: Record<string, unknown>): Promise<T>;
}

/**
 * Convex conversation repository
 */
export class ConvexConversationRepository implements ConversationRepository {
  constructor(private client: ConvexClient) {}

  async list(userId: string): Promise<Conversation[]> {
    return this.client.query('conversations:list', { userId });
  }

  async getById(id: string): Promise<Conversation | null> {
    return this.client.query('conversations:getById', { id });
  }

  async create(data: CreateConversation): Promise<Conversation> {
    return this.client.mutation('conversations:create', data as unknown as Record<string, unknown>);
  }

  async update(id: string, data: Partial<Conversation>): Promise<void> {
    await this.client.mutation('conversations:update', { id, ...data });
  }

  async updateTitle(id: string, title: string): Promise<void> {
    await this.client.mutation('conversations:updateTitle', { id, title });
  }

  async delete(id: string): Promise<void> {
    await this.client.mutation('conversations:delete', { id });
  }
}

/**
 * Convex message repository
 */
export class ConvexMessageRepository implements MessageRepository {
  constructor(private client: ConvexClient) {}

  async getByConversation(conversationId: string): Promise<DBMessage[]> {
    return this.client.query('messages:getByConversation', { conversationId });
  }

  async getById(id: string): Promise<DBMessage | null> {
    return this.client.query('messages:getById', { id });
  }

  async create(data: CreateMessage): Promise<DBMessage> {
    return this.client.mutation('messages:create', data as unknown as Record<string, unknown>);
  }

  async saveAssistantMessage(data: {
    conversationId: string;
    content: string;
    reasoning?: string;
    toolCalls?: ToolCall[];
    inputTokens?: number;
    outputTokens?: number;
  }): Promise<DBMessage> {
    return this.client.mutation('messages:saveAssistant', data);
  }

  async saveToolMessage(data: {
    conversationId: string;
    toolCallId: string;
    toolName: string;
    content: string;
  }): Promise<DBMessage> {
    return this.client.mutation('messages:saveTool', data);
  }
}

/**
 * Convex session repository
 */
export class ConvexSessionRepository implements SessionRepository {
  constructor(private client: ConvexClient) {}

  async getById(id: string): Promise<DBSession | null> {
    return this.client.query('sessions:getById', { id });
  }

  async getByStreamId(streamId: string): Promise<DBSession | null> {
    return this.client.query('sessions:getByStreamId', { streamId });
  }

  async getActive(conversationId: string): Promise<DBSession | null> {
    return this.client.query('sessions:getActive', { conversationId });
  }

  async create(data: CreateSession): Promise<DBSession> {
    return this.client.mutation('sessions:create', data as unknown as Record<string, unknown>);
  }

  async updateStatus(id: string, status: SessionStatus, extra?: Partial<DBSession>): Promise<void> {
    await this.client.mutation('sessions:updateStatus', { id, status, ...extra });
  }

  async complete(id: string, data: {
    assistantMessageId?: string;
    accumulatedContent?: string;
    accumulatedReasoning?: string;
    inputTokens?: number;
    outputTokens?: number;
  }): Promise<void> {
    await this.client.mutation('sessions:complete', { id, ...data });
  }
}

/**
 * Create Convex repositories bundle
 */
export function createConvexRepositories(client: ConvexClient): Repositories {
  return {
    conversations: new ConvexConversationRepository(client),
    messages: new ConvexMessageRepository(client),
    sessions: new ConvexSessionRepository(client),
  };
}
