/**
 * SAGE Handler
 *
 * Main entry point for creating chat handlers.
 * This is what makes SAGE easy to use in Next.js apps.
 */

import type { SageConfig, Message } from './types';
import type { AgentCallbacks } from './agent/types';
import type { StreamStore } from './streaming/types';
import type { ToolRegistry } from './tools/types';
import type { Repositories } from './db/types';
import type { ConvexClient } from './db/convex';
import type { WorkingMemoryManager, MemoryStore, VectorStore, ContextConfig } from './context/types';
import { createSession, buildSystemPrompt } from './agent/session';
import { createToolRegistry } from './tools/registry';
import { createRedisStreamStore } from './streaming/redis';
import { createMemoryStreamStore } from './streaming/memory';
import { createMemoryRepositories } from './db/memory';
import { createConvexRepositories } from './db/convex';
import { createWorkingMemory } from './context/working-memory';
import { InMemoryStore } from './context/adapters/in-memory-store';
import { createMemoryTools } from './context/memory-tools';


/**
 * Handler context with initialized components
 */
export interface HandlerContext {
  config: SageConfig;
  streamStore: StreamStore;
  tools: ToolRegistry;
  repositories: Repositories;
  workingMemory?: WorkingMemoryManager;
  memoryStore?: MemoryStore;
  vectorStore?: VectorStore;
  contextConfig?: ContextConfig;
}

/**
 * Options for initializing SAGE
 */
export interface InitializeOptions {
  convexClient?: ConvexClient;
  /** Custom memory store (default: InMemoryStore) */
  memoryStore?: MemoryStore;
  /** Custom vector store for semantic search */
  vectorStore?: VectorStore;
  /** Custom embeddings adapter for semantic search */
  embeddings?: import('./context/types').EmbeddingsAdapter;
}

/**
 * Initialize SAGE components from config
 */
export async function initializeSage(
  config: SageConfig,
  options: InitializeOptions = {}
): Promise<HandlerContext> {
  // Initialize stream store
  let streamStore: StreamStore;
  if (config.streaming?.type === 'redis') {
    streamStore = createRedisStreamStore(config.streaming.url, {
      keyPrefix: config.streaming.keyPrefix,
      defaultTtl: config.streaming.ttl,
    });
  } else {
    streamStore = createMemoryStreamStore();
  }

  // Initialize tool registry
  const tools = createToolRegistry();

  // Register tools from config
  if (config.tools) {
    for (const tool of config.tools) {
      if (typeof tool === 'object' && 'name' in tool) {
        tools.register(tool);
      }
    }
  }

  // Initialize repositories based on database config
  let repositories: Repositories;
  if (config.database?.type === 'convex' && options.convexClient) {
    repositories = createConvexRepositories(options.convexClient);
  } else {
    // Default to memory repositories (suitable for testing or simple setups)
    repositories = createMemoryRepositories();
  }

  // Initialize working memory if configured
  let workingMemory: WorkingMemoryManager | undefined;
  let memoryStore: MemoryStore | undefined;
  let vectorStore: VectorStore | undefined;
  let contextConfig: ContextConfig | undefined;

  if (config.context?.workingMemory?.enabled) {
    memoryStore = options.memoryStore ?? new InMemoryStore();
    vectorStore = options.vectorStore;

    workingMemory = createWorkingMemory({
      enabled: true,
      autoExtract: config.context.workingMemory.autoExtract ?? true,
      extractionModel: config.context.workingMemory.extractionModel,
      maxMemoriesInPrompt: config.context.workingMemory.maxMemoriesInPrompt,
      store: memoryStore,
      embeddings: options.embeddings,
      vectorStore,
      provider: config.provider?.apiKey
        ? {
            apiKey: config.provider.apiKey,
            baseUrl: config.provider.baseUrl || 'https://api.openai.com/v1',
          }
        : undefined,
    });

    // Register memory tools
    const memTools = createMemoryTools(workingMemory, {
      memory: memoryStore,
      vector: vectorStore,
    });
    for (const tool of memTools) {
      tools.register(tool);
    }
  }

  // Build context config if context management is enabled
  if (config.context?.enabled) {
    contextConfig = {
      model: config.model ?? 'gpt-4o',
      contextWindow: config.context.contextWindow,
      maxResponseTokens: config.context.maxResponseTokens ?? config.maxTokens ?? 4096,
      workingMemory,
      summary: config.context.summary?.enabled && config.provider?.apiKey
        ? {
            model: config.context.summary.model,
            targetTokens: config.context.summary.targetTokens,
            provider: {
              apiKey: config.provider.apiKey,
              baseUrl: config.provider.baseUrl || 'https://api.openai.com/v1',
            },
          }
        : undefined,
    };
  }

  return {
    config,
    streamStore,
    tools,
    repositories,
    workingMemory,
    memoryStore,
    vectorStore,
    contextConfig,
  };
}

/**
 * Chat request body
 */
export interface ChatRequest {
  conversationId: string;
  message: string;
  userId: string;
  attachments?: Array<{
    type: 'image' | 'pdf' | 'file';
    url: string;
    name?: string;
  }>;
}

/**
 * Chat response
 */
export interface ChatResponse {
  sessionId: string;
  streamId: string;
  conversationId: string;
}

/**
 * Handler options
 */
export interface HandlerOptions {
  convexClient?: ConvexClient;
}

/**
 * Create a chat handler for Next.js API routes
 *
 * @example
 * ```typescript
 * // app/api/chat/route.ts
 * import { createChatHandler } from '@sage/core';
 * import config from '@/sage.config';
 *
 * export const POST = createChatHandler(config);
 *
 * // With Convex client:
 * import { ConvexHttpClient } from 'convex/browser';
 * const convex = new ConvexHttpClient(process.env.NEXT_PUBLIC_CONVEX_URL!);
 * export const POST = createChatHandler(config, { convexClient: convex });
 * ```
 */
export function createChatHandler(config: SageConfig, options: HandlerOptions = {}) {
  let context: HandlerContext | null = null;

  return async function handler(request: Request): Promise<Response> {
    // Initialize on first request
    if (!context) {
      context = await initializeSage(config, options);
    }

    try {
      const body = await request.json() as ChatRequest;
      const { conversationId, message, userId, attachments } = body;

      // Validate required fields
      if (!conversationId || !message || !userId) {
        return new Response(
          JSON.stringify({ error: 'Missing required fields: conversationId, message, userId' }),
          { status: 400, headers: { 'Content-Type': 'application/json' } }
        );
      }

      // Get existing messages for conversation
      const existingMessages = await context.repositories.messages.getByConversation(conversationId);

      // Build user message
      const userMessage: Message = {
        role: 'user',
        content: message,
      };

      // Add attachments if provided
      if (attachments && attachments.length > 0) {
        userMessage.content = [
          { type: 'text', text: message },
          ...attachments.map(a => ({
            type: a.type as 'image' | 'file',
            imageUrl: a.type === 'image' ? a.url : undefined,
            fileUrl: a.type !== 'image' ? a.url : undefined,
          })),
        ];
      }

      // Save user message
      await context.repositories.messages.create({
        conversationId,
        role: 'user',
        content: message,
        attachments: attachments?.map(a => ({
          type: a.type,
          url: a.url,
          name: a.name,
        })),
      });

      // Build messages array
      const messages: Message[] = [
        ...existingMessages.map(m => ({
          role: m.role,
          content: m.content,
          toolCalls: m.toolCalls,
          toolCallId: m.toolCallId,
          reasoning: m.reasoning,
        })),
        userMessage,
      ];

      // Build system prompt
      const systemPrompt = buildSystemPrompt({
        agentName: config.agent?.name,
        basePrompt: config.agent?.systemPrompt,
        hasMemoryTools: !!context.workingMemory,
      });

      // Create and start session
      const { sessionId, streamId, result } = await createSession({
        conversationId,
        userId,
        systemPrompt,
        messages,
        tools: context.tools,
        streamStore: context.streamStore,
        config: context.config,
        sessionRepository: context.repositories.sessions,
        messageRepository: context.repositories.messages,
        workingMemory: context.workingMemory,
        contextConfig: context.contextConfig,
      });

      // Don't await result - it runs in background
      result.catch(err => {
        console.error('[SAGE] Session error:', err);
      });

      // Return session info for client to poll
      return new Response(
        JSON.stringify({
          sessionId,
          streamId,
          conversationId,
        } satisfies ChatResponse),
        { status: 200, headers: { 'Content-Type': 'application/json' } }
      );
    } catch (error) {
      console.error('[SAGE] Handler error:', error);
      return new Response(
        JSON.stringify({ error: error instanceof Error ? error.message : 'Internal error' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }
  };
}

/**
 * Create a stream reader handler for Next.js API routes
 *
 * @example
 * ```typescript
 * // app/api/chat/stream/route.ts
 * import { createStreamHandler } from '@sage/core';
 * import config from '@/sage.config';
 *
 * export const GET = createStreamHandler(config);
 * ```
 */
export function createStreamHandler(config: SageConfig, options: HandlerOptions = {}) {
  let context: HandlerContext | null = null;

  return async function handler(request: Request): Promise<Response> {
    // Initialize on first request
    if (!context) {
      context = await initializeSage(config, options);
    }

    try {
      const url = new URL(request.url);
      const streamId = url.searchParams.get('streamId');
      const cursor = url.searchParams.get('cursor') || '0';
      const count = parseInt(url.searchParams.get('count') || '100', 10);

      if (!streamId) {
        return new Response(
          JSON.stringify({ error: 'Missing streamId parameter' }),
          { status: 400, headers: { 'Content-Type': 'application/json' } }
        );
      }

      // Read from stream
      const entries = await context.streamStore.read(streamId, cursor, count);
      const meta = await context.streamStore.getMeta(streamId);

      // Check if done
      const lastEntry = entries[entries.length - 1];
      const isDone = lastEntry?.data.type === 'status' &&
        ['completed', 'failed', 'cancelled'].includes(lastEntry.data.status || '');

      return new Response(
        JSON.stringify({
          chunks: entries.map(e => ({
            id: e.id,
            ...e.data,
          })),
          cursor: lastEntry?.id || cursor,
          done: isDone,
          status: meta?.status || 'unknown',
        }),
        { status: 200, headers: { 'Content-Type': 'application/json' } }
      );
    } catch (error) {
      console.error('[SAGE] Stream handler error:', error);
      return new Response(
        JSON.stringify({ error: error instanceof Error ? error.message : 'Internal error' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }
  };
}
