/**
 * Agentic Loop
 *
 * The core recursive loop that processes messages, handles tool calls,
 * and streams responses using the OpenAI Responses API.
 *
 * PARALLEL TOOL EXECUTION:
 * When the LLM returns multiple tool calls in a single response, they are
 * executed in parallel using Promise.all(). This enables:
 * - Multiple subagents running simultaneously
 * - Faster execution of independent tools
 * - The LLM controls parallelism by choosing how many tools to call per turn
 *
 * Error handling: Each tool's errors are captured individually. If one tool
 * fails, others continue running. All results (success or error) are collected
 * and passed back to the LLM for the next iteration.
 *
 * LIFECYCLE HOOKS:
 * The loop calls optional hooks at key points for observability and interception:
 * - beforeLLMCall: Before sending request to LLM
 * - afterLLMCall: After receiving LLM response
 * - beforeToolExecution: Before executing each tool (can modify args)
 * - afterToolExecution: After tool completes (success or failure)
 * - onError: When any error occurs
 * - onComplete: When agent completes successfully
 */

import type { Message, ToolCall, AgentResult, HookContext } from '../types';
import type { AgentContext, StreamAccumulator } from './types';
import { handleStreamEvent } from './stream-handler';
import { withRetry, LLM_RETRY_CONFIG } from '../utils/retry';
import {
  validateToolArgs,
  executeWithTimeout,
  truncateResult,
  formatToolError,
  formatValidationError,
  DEFAULT_TOOL_TIMEOUT,
  DEFAULT_MAX_RESULT_SIZE,
} from '../tools/executor';
import { manageContext } from '../context/context-manager';

/**
 * Default options for the agentic loop
 */
const DEFAULT_MAX_DEPTH = 30;

/**
 * Create a HookContext from AgentContext
 */
function createHookContext(context: AgentContext): HookContext {
  return {
    sessionId: context.sessionId,
    conversationId: context.conversationId,
    userId: context.userId,
    streamId: context.streamId,
    agentId: context.agentId,
    agentDepth: context.agentDepth,
    messages: context.messages,
  };
}

/**
 * Process a message with tool loop support
 *
 * This is the core agentic loop that:
 * 1. Sends messages to the LLM via Responses API
 * 2. Streams the response
 * 3. If tool calls are returned, executes them and recurses
 * 4. If no tool calls, returns the final result
 *
 * @param context - Agent context with messages, tools, config, etc.
 * @param depth - Current recursion depth (for safety)
 * @returns The final agent result
 */
export async function processWithToolLoop(
  context: AgentContext,
  depth: number = 0
): Promise<AgentResult> {
  const maxDepth = context.config.agent?.maxDepth ?? DEFAULT_MAX_DEPTH;
  const hooks = context.config.hooks;
  const hookContext = createHookContext(context);

  // Safety check: prevent infinite loops
  if (depth >= maxDepth) {
    const error = new Error(`Tool loop exceeded max depth of ${maxDepth}`);
    await hooks?.onError?.(error, hookContext);
    throw error;
  }

  const { sessionId, streamId, systemPrompt, messages, tools, streamStore, config, callbacks, agentId, agentDepth } = context;

  // Notify status change
  callbacks?.onStatusChange?.('running');

  // Write running status to stream
  await streamStore.append(streamId, {
    type: 'status',
    content: 'running',
    timestamp: Date.now(),
    status: 'running',
    agentId,
    agentDepth,
  });

  // Validate provider config
  if (!config.provider?.apiKey) {
    const error = new Error('SAGE: provider.apiKey is required. Set OPENAI_API_KEY or configure provider.apiKey.');
    await hooks?.onError?.(error, hookContext);
    throw error;
  }

  // Get provider config
  const providerConfig = {
    apiKey: config.provider.apiKey,
    baseUrl: config.provider.baseUrl || 'https://api.openai.com/v1',
    model: config.model ?? 'gpt-4o',
    temperature: config.temperature,
    maxTokens: config.maxTokens,
    parallelToolCalls: config.parallelToolCalls ?? true,
  };

  // Apply context management (sliding window, summary, working memory)
  let finalSystemPrompt = systemPrompt;
  let finalMessages = messages;

  if (context.contextConfig) {
    try {
      const contextResult = await manageContext({
        messages,
        systemPrompt,
        userId: context.userId,
        config: context.contextConfig,
        existingSummary: context.existingSummary,
      });
      finalMessages = contextResult.messages;
      finalSystemPrompt = contextResult.systemPrompt;
      // Persist new summary for next iteration
      if (contextResult.newSummary) {
        context.existingSummary = contextResult.newSummary;
      }
    } catch (err) {
      console.warn('[SAGE] Context management failed, using raw messages:', err);
    }
  }

  // Get tools in API format
  const apiTools = tools.toAPIFormat();

  // Normalize messages to Responses API format
  const apiMessages = normalizeMessagesToResponsesAPI(finalMessages);

  // === HOOK: beforeLLMCall ===
  try {
    await hooks?.beforeLLMCall?.(hookContext);
  } catch (hookError) {
    // Hook errors should not stop execution, just log them
    console.warn('[SAGE] beforeLLMCall hook error:', hookError);
  }

  // Make request to Responses API with optional retry
  const retryConfig = config.retry;
  const makeRequest = async (): Promise<Response> => {
    const res = await fetch(`${providerConfig.baseUrl}/responses`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${providerConfig.apiKey}`,
        'OpenAI-Beta': 'responses=v1',
      },
      body: JSON.stringify({
        model: providerConfig.model,
        instructions: finalSystemPrompt,
        input: apiMessages,
        tools: apiTools.length > 0 ? apiTools : undefined,
        parallel_tool_calls: providerConfig.parallelToolCalls,
        stream: true,
        temperature: providerConfig.temperature,
        max_output_tokens: providerConfig.maxTokens,
      }),
    });

    // Throw on non-OK responses to trigger retry for retryable status codes
    if (!res.ok) {
      const errorBody = await res.text();
      throw new Error(`Responses API error: ${res.status} - ${errorBody}`);
    }

    return res;
  };

  let response: Response;
  try {
    // Use retry if configured, otherwise make single request
    if (retryConfig) {
      response = await withRetry(makeRequest, {
        ...LLM_RETRY_CONFIG,
        ...retryConfig,
        onRetry: (attempt, error, delay) => {
          console.warn(`[SAGE] LLM request retry ${attempt} after ${delay}ms: ${error.message}`);
          retryConfig.onRetry?.(attempt, error, delay);
        },
      });
    } else {
      response = await makeRequest();
    }
  } catch (fetchError) {
    const error = fetchError instanceof Error ? fetchError : new Error(String(fetchError));
    await hooks?.onError?.(error, hookContext);
    throw error;
  }

  // Process SSE stream
  const reader = response.body?.getReader();
  if (!reader) {
    const error = new Error('No response body');
    await hooks?.onError?.(error, hookContext);
    throw error;
  }

  const accumulator: StreamAccumulator = {
    content: '',
    reasoning: '',
    toolCalls: [],
    inputTokens: 0,
    outputTokens: 0,
  };

  const decoder = new TextDecoder();
  let buffer = '';

  const handlerContext = {
    streamStore,
    streamId,
    accumulator,
    callbacks,
    agentId,
    agentDepth,
  };

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (!line.startsWith('data: ')) continue;
        const data = line.slice(6).trim();
        if (data === '[DONE]') continue;
        if (!data) continue;

        try {
          const event = JSON.parse(data);
          await handleStreamEvent(event, handlerContext);
        } catch {
          // Ignore parse errors for incomplete chunks
        }
      }
    }
  } finally {
    reader.releaseLock();
  }

  // === HOOK: afterLLMCall ===
  try {
    await hooks?.afterLLMCall?.(hookContext, {
      content: accumulator.content,
      reasoning: accumulator.reasoning || undefined,
      toolCalls: accumulator.toolCalls,
      inputTokens: accumulator.inputTokens,
      outputTokens: accumulator.outputTokens,
    });
  } catch (hookError) {
    console.warn('[SAGE] afterLLMCall hook error:', hookError);
  }

  // Check if we have tool calls to process
  const validToolCalls = accumulator.toolCalls.filter(
    tc => tc.function?.name && tc.function.name.trim() !== ''
  );

  if (validToolCalls.length > 0) {
    // Notify tool loop status
    callbacks?.onStatusChange?.('tool_loop');

    await streamStore.append(streamId, {
      type: 'status',
      content: 'tool_loop',
      timestamp: Date.now(),
      status: 'tool_loop',
      agentId,
      agentDepth,
    });

    // Execute ALL tools in PARALLEL and collect results
    // This applies to both regular tools and subagent delegations
    const toolResults: Message[] = await Promise.all(
      validToolCalls.map(async (toolCall): Promise<Message> => {
        const toolName = toolCall.function.name;
        const toolDef = tools.get(toolName);
        const toolInfo = {
          name: toolName,
          description: toolDef?.description || '',
        };

        // Notify tool call
        callbacks?.onToolCall?.(toolCall);

        // Write tool call to stream
        await streamStore.append(streamId, {
          type: 'tool_call',
          content: '',
          timestamp: Date.now(),
          toolCallId: toolCall.id,
          toolName,
          toolArguments: toolCall.function.arguments,
          agentId,
          agentDepth,
        });

        let args: Record<string, unknown>;
        try {
          // Parse arguments
          args = JSON.parse(toolCall.function.arguments || '{}');
        } catch (parseError) {
          const error = new Error(`Failed to parse tool arguments: ${parseError}`);
          await hooks?.onError?.(error, hookContext);
          
          const errorResponse = JSON.stringify({
            error: true,
            message: error.message,
            toolName,
            suggestion: 'Invalid JSON arguments provided.',
          });

          callbacks?.onToolResult?.(toolCall.id, errorResponse);
          await streamStore.append(streamId, {
            type: 'tool_result',
            content: errorResponse,
            timestamp: Date.now(),
            toolCallId: toolCall.id,
            toolName,
            agentId,
            agentDepth,
          });

          return {
            role: 'tool',
            content: errorResponse,
            toolCallId: toolCall.id,
          };
        }

        // === HOOK: beforeToolExecution ===
        try {
          const modifiedArgs = await hooks?.beforeToolExecution?.(toolInfo, args, hookContext);
          if (modifiedArgs !== undefined) {
            args = modifiedArgs;
          }
        } catch (hookError) {
          // If beforeToolExecution throws, skip this tool
          const error = hookError instanceof Error ? hookError : new Error(String(hookError));
          console.warn('[SAGE] beforeToolExecution hook error:', error);
          
          // Call afterToolExecution with the error
          try {
            await hooks?.afterToolExecution?.(toolInfo, args, null, error, hookContext);
          } catch {
            // Ignore errors in afterToolExecution
          }

          const errorResponse = JSON.stringify({
            error: true,
            message: `Tool execution blocked: ${error.message}`,
            toolName,
          });

          callbacks?.onToolResult?.(toolCall.id, errorResponse);
          await streamStore.append(streamId, {
            type: 'tool_result',
            content: errorResponse,
            timestamp: Date.now(),
            toolCallId: toolCall.id,
            toolName,
            agentId,
            agentDepth,
          });

          return {
            role: 'tool',
            content: errorResponse,
            toolCallId: toolCall.id,
          };
        }

        try {
          // Get tool definition for validation and timeout/size settings
          const toolDef = tools.get(toolName);
          
          // Validate arguments if tool definition exists
          if (toolDef) {
            const validation = validateToolArgs(toolDef, args);
            if (!validation.valid) {
              const errorResponse = formatValidationError(validation.errors, toolName);
              
              callbacks?.onToolResult?.(toolCall.id, errorResponse);
              await streamStore.append(streamId, {
                type: 'tool_result',
                content: errorResponse,
                timestamp: Date.now(),
                toolCallId: toolCall.id,
                toolName,
                agentId,
                agentDepth,
              });

              return {
                role: 'tool',
                content: errorResponse,
                toolCallId: toolCall.id,
              };
            }
          }

          // Determine timeout and max result size
          const toolTimeout = toolDef?.timeout ?? context.config.agent?.toolTimeout ?? DEFAULT_TOOL_TIMEOUT;
          const maxResultSize = toolDef?.maxResultSize ?? context.config.agent?.maxToolResultSize ?? DEFAULT_MAX_RESULT_SIZE;

          // Execute tool with timeout
          const result = await executeWithTimeout(
            () => tools.execute(toolName, args, {
              userId: context.userId,
              conversationId: context.conversationId,
              sessionId: context.sessionId,
            }),
            toolTimeout,
            `Tool "${toolName}" timed out after ${toolTimeout}ms`
          );

          // Stringify and apply size limiting
          let resultStr = typeof result === 'string' ? result : JSON.stringify(result);
          if (resultStr.length > maxResultSize) {
            resultStr = truncateResult(resultStr, maxResultSize);
          }

          // === HOOK: afterToolExecution (success) ===
          try {
            await hooks?.afterToolExecution?.(toolInfo, args, result, null, hookContext);
          } catch (hookError) {
            console.warn('[SAGE] afterToolExecution hook error:', hookError);
          }

          // Notify tool result
          callbacks?.onToolResult?.(toolCall.id, resultStr);

          // Write result to stream
          await streamStore.append(streamId, {
            type: 'tool_result',
            content: resultStr,
            timestamp: Date.now(),
            toolCallId: toolCall.id,
            toolName,
            agentId,
            agentDepth,
          });

          return {
            role: 'tool',
            content: resultStr,
            toolCallId: toolCall.id,
          };
        } catch (error) {
          const errorObj = error instanceof Error ? error : new Error(String(error));

          // === HOOK: afterToolExecution (failure) ===
          try {
            await hooks?.afterToolExecution?.(toolInfo, args, null, errorObj, hookContext);
          } catch (hookError) {
            console.warn('[SAGE] afterToolExecution hook error:', hookError);
          }

          // Also call onError hook
          await hooks?.onError?.(errorObj, hookContext);

          // Format error with recovery suggestion
          const errorResponse = formatToolError(errorObj, toolName, args);

          callbacks?.onToolResult?.(toolCall.id, errorResponse);

          await streamStore.append(streamId, {
            type: 'tool_result',
            content: errorResponse,
            timestamp: Date.now(),
            toolCallId: toolCall.id,
            toolName,
            agentId,
            agentDepth,
          });

          return {
            role: 'tool',
            content: errorResponse,
            toolCallId: toolCall.id,
          };
        }
      })
    );

    // Build new messages with tool results
    const newMessages: Message[] = [
      ...messages,
      {
        role: 'assistant',
        content: accumulator.content,
        toolCalls: validToolCalls,
        reasoning: accumulator.reasoning || undefined,
      },
      ...toolResults,
    ];

    // Recurse with tool results
    return processWithToolLoop(
      { ...context, messages: newMessages },
      depth + 1
    );
  }

  // No tool calls - complete
  const result: AgentResult = {
    content: accumulator.content,
    reasoning: accumulator.reasoning || undefined,
    toolCalls: [],
    inputTokens: accumulator.inputTokens,
    outputTokens: accumulator.outputTokens,
  };

  // === HOOK: onComplete ===
  try {
    await hooks?.onComplete?.(result, hookContext);
  } catch (hookError) {
    console.warn('[SAGE] onComplete hook error:', hookError);
  }

  // Notify completion
  callbacks?.onComplete?.(result);
  callbacks?.onStatusChange?.('completed');

  // Write completion status to stream
  await streamStore.append(streamId, {
    type: 'status',
    content: 'completed',
    timestamp: Date.now(),
    status: 'completed',
    agentId,
    agentDepth,
  });

  return result;
}

/**
 * Normalize messages to OpenAI Responses API format
 */
function normalizeMessagesToResponsesAPI(messages: Message[]): unknown[] {
  const result: unknown[] = [];

  for (const m of messages) {
    if (m.role === 'tool') {
      // Tool result -> function_call_output
      result.push({
        type: 'function_call_output',
        call_id: m.toolCallId,
        output: typeof m.content === 'string' ? m.content : JSON.stringify(m.content),
      });
    } else if (m.role === 'assistant' && m.toolCalls && m.toolCalls.length > 0) {
      // Assistant with tool calls
      if (m.content) {
        result.push({
          role: 'assistant',
          content: typeof m.content === 'string' ? m.content : m.content,
        });
      }
      // Add each function_call
      for (const tc of m.toolCalls) {
        result.push({
          type: 'function_call',
          call_id: tc.id,
          name: tc.function.name,
          arguments: tc.function.arguments,
        });
      }
    } else if (m.role === 'user' && Array.isArray(m.content)) {
      // Multimodal user message
      const contentParts = m.content.map(part => {
        if (part.type === 'text') {
          return { type: 'input_text', text: part.text };
        } else if (part.type === 'image') {
          return { type: 'input_image', image_url: part.imageUrl };
        } else if (part.type === 'file') {
          return { type: 'input_file', file_url: part.fileUrl };
        }
        return { type: 'input_text', text: '' };
      });
      result.push({ role: m.role, content: contentParts });
    } else {
      // Regular message
      result.push({
        role: m.role,
        content: m.content,
      });
    }
  }

  return result;
}
