/**
 * Sliding Window
 *
 * Applies a backwards sliding window to fit conversation messages
 * within the available token budget. Preserves tool call integrity.
 */

import type { Message } from '../types';
import type { Tokenizer, TokenBudget, WindowResult } from './types';
import { estimateMessageTokens, estimateTokens, getTokenizer } from './token-counter';
import { adjustSplitForToolIntegrity, validateToolCallIntegrity } from './tool-integrity';

/**
 * Options for applying the sliding window
 */
export interface WindowOptions {
  /** Messages to window */
  messages: Message[];
  /** System prompt text (for budget calculation) */
  systemPrompt: string;
  /** Total context window size */
  contextWindow: number;
  /** Max tokens reserved for response */
  maxResponseTokens: number;
  /** Tokens used by existing summary (default: 0) */
  summaryTokens?: number;
  /** Tokens used by working memory injection (default: 0) */
  memoryTokens?: number;
  /** Custom tokenizer */
  tokenizer?: Tokenizer;
}

/**
 * Apply a backwards sliding window to messages.
 *
 * Starts from the most recent message and works backwards,
 * including as many messages as fit in the available token budget.
 * Preserves tool call/result pair integrity.
 *
 * @returns WindowResult with recent messages, old messages, and budget info
 */
export function applyWindow(options: WindowOptions): WindowResult {
  const {
    messages,
    systemPrompt,
    contextWindow,
    maxResponseTokens,
    summaryTokens = 0,
    memoryTokens = 0,
    tokenizer,
  } = options;

  const tok = getTokenizer(tokenizer);
  const systemPromptTokens = estimateTokens(systemPrompt, tok);

  // Calculate budget
  const availableForHistory = Math.max(
    0,
    contextWindow - systemPromptTokens - summaryTokens - memoryTokens - maxResponseTokens
  );

  const budget: TokenBudget = {
    contextWindow,
    systemPrompt: systemPromptTokens,
    workingMemory: memoryTokens,
    existingSummary: summaryTokens,
    maxResponse: maxResponseTokens,
    availableForHistory,
  };

  // If all messages fit, no truncation needed
  let totalTokens = 0;
  const messageTokens: number[] = [];
  for (const msg of messages) {
    const tokens = estimateMessageTokens(msg, tok);
    messageTokens.push(tokens);
    totalTokens += tokens;
  }

  if (totalTokens <= availableForHistory) {
    return {
      recentMessages: [...messages],
      oldMessages: [],
      wasTruncated: false,
      budget,
      recentTokens: totalTokens,
    };
  }

  // Work backwards to find how many recent messages fit
  let recentTokens = 0;
  let splitIndex = messages.length; // Start assuming nothing fits

  for (let i = messages.length - 1; i >= 0; i--) {
    const msgTokens = messageTokens[i];
    if (recentTokens + msgTokens > availableForHistory) {
      splitIndex = i + 1;
      break;
    }
    recentTokens += msgTokens;

    // If we've included everything
    if (i === 0) {
      splitIndex = 0;
    }
  }

  // Adjust split point for tool call integrity
  splitIndex = adjustSplitForToolIntegrity(messages, splitIndex);

  // Split messages
  const oldMessages = messages.slice(0, splitIndex);
  let recentMessages = messages.slice(splitIndex);

  // Validate integrity of the recent messages
  const integrityResult = validateToolCallIntegrity(recentMessages);
  if (!integrityResult.valid) {
    recentMessages = integrityResult.messages;
  }

  // Recalculate recent tokens after integrity fixes
  recentTokens = 0;
  for (const msg of recentMessages) {
    recentTokens += estimateMessageTokens(msg, tok);
  }

  return {
    recentMessages,
    oldMessages,
    wasTruncated: true,
    budget,
    recentTokens,
  };
}
