/**
 * Retry Utility
 *
 * Provides retry functionality with exponential backoff for handling
 * transient failures in LLM API calls and tool executions.
 */

/**
 * Retry configuration
 */
export interface RetryConfig {
  /** Maximum number of retry attempts (default: 3) */
  maxAttempts?: number;

  /** Initial delay in milliseconds (default: 1000) */
  initialDelay?: number;

  /** Maximum delay in milliseconds (default: 30000) */
  maxDelay?: number;

  /** Backoff multiplier (default: 2) */
  backoffMultiplier?: number;

  /** Jitter factor 0-1 to randomize delays (default: 0.1) */
  jitter?: number;

  /** Function to determine if error is retryable (default: retries all errors) */
  isRetryable?: (error: Error) => boolean;

  /** Called before each retry attempt */
  onRetry?: (attempt: number, error: Error, delay: number) => void;
}

/**
 * Default retry configuration
 */
export const DEFAULT_RETRY_CONFIG: Required<Omit<RetryConfig, 'onRetry' | 'isRetryable'>> = {
  maxAttempts: 3,
  initialDelay: 1000,
  maxDelay: 30000,
  backoffMultiplier: 2,
  jitter: 0.1,
};

/**
 * Errors that are typically retryable (transient)
 */
const RETRYABLE_STATUS_CODES = [
  408, // Request Timeout
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
];

/**
 * Default function to check if an error is retryable
 */
export function isRetryableError(error: Error): boolean {
  const message = error.message.toLowerCase();

  // Network errors
  if (
    message.includes('network') ||
    message.includes('timeout') ||
    message.includes('econnreset') ||
    message.includes('econnrefused') ||
    message.includes('socket hang up')
  ) {
    return true;
  }

  // Rate limiting
  if (message.includes('rate limit') || message.includes('too many requests')) {
    return true;
  }

  // Check for status codes in error message
  for (const code of RETRYABLE_STATUS_CODES) {
    if (message.includes(`${code}`)) {
      return true;
    }
  }

  // OpenAI specific errors
  if (
    message.includes('overloaded') ||
    message.includes('capacity') ||
    message.includes('temporarily unavailable')
  ) {
    return true;
  }

  return false;
}

/**
 * Calculate delay with exponential backoff and jitter
 */
export function calculateBackoffDelay(
  attempt: number,
  config: Required<Omit<RetryConfig, 'onRetry' | 'isRetryable'>>
): number {
  const { initialDelay, maxDelay, backoffMultiplier, jitter } = config;

  // Calculate exponential delay
  const exponentialDelay = initialDelay * Math.pow(backoffMultiplier, attempt - 1);

  // Apply max delay cap
  const cappedDelay = Math.min(exponentialDelay, maxDelay);

  // Add jitter
  const jitterRange = cappedDelay * jitter;
  const jitterValue = Math.random() * jitterRange * 2 - jitterRange;

  return Math.max(0, Math.round(cappedDelay + jitterValue));
}

/**
 * Sleep for a specified duration
 */
export function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Execute a function with retry logic
 *
 * @example
 * ```typescript
 * const result = await withRetry(
 *   async () => await fetch('https://api.openai.com/v1/chat/completions', ...),
 *   {
 *     maxAttempts: 3,
 *     onRetry: (attempt, error, delay) => {
 *       console.log(`Retry attempt ${attempt} after ${delay}ms: ${error.message}`);
 *     },
 *   }
 * );
 * ```
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  config: RetryConfig = {}
): Promise<T> {
  const {
    maxAttempts = DEFAULT_RETRY_CONFIG.maxAttempts,
    initialDelay = DEFAULT_RETRY_CONFIG.initialDelay,
    maxDelay = DEFAULT_RETRY_CONFIG.maxDelay,
    backoffMultiplier = DEFAULT_RETRY_CONFIG.backoffMultiplier,
    jitter = DEFAULT_RETRY_CONFIG.jitter,
    isRetryable = isRetryableError,
    onRetry,
  } = config;

  const fullConfig = { maxAttempts, initialDelay, maxDelay, backoffMultiplier, jitter };

  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      // Check if we should retry
      const shouldRetry = attempt < maxAttempts && isRetryable(lastError);

      if (!shouldRetry) {
        throw lastError;
      }

      // Calculate delay
      const delay = calculateBackoffDelay(attempt, fullConfig);

      // Notify retry
      onRetry?.(attempt, lastError, delay);

      // Wait before retrying
      await sleep(delay);
    }
  }

  // Should never reach here, but TypeScript requires it
  throw lastError || new Error('Retry failed');
}

/**
 * Create a retry wrapper with preset configuration
 *
 * @example
 * ```typescript
 * const retryFetch = createRetryWrapper({
 *   maxAttempts: 5,
 *   onRetry: (attempt) => console.log(`Retry ${attempt}`),
 * });
 *
 * const result = await retryFetch(async () => {
 *   return await fetch(url);
 * });
 * ```
 */
export function createRetryWrapper(
  defaultConfig: RetryConfig
): <T>(fn: () => Promise<T>, overrides?: RetryConfig) => Promise<T> {
  return <T>(fn: () => Promise<T>, overrides?: RetryConfig): Promise<T> => {
    return withRetry(fn, { ...defaultConfig, ...overrides });
  };
}

/**
 * Retry configuration for LLM API calls
 *
 * More aggressive retry for transient API errors
 */
export const LLM_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  initialDelay: 1000,
  maxDelay: 60000,
  backoffMultiplier: 2,
  jitter: 0.2,
  isRetryable: isRetryableError,
};

/**
 * Retry configuration for tool executions
 *
 * Less aggressive retry, only for network issues
 */
export const TOOL_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 2,
  initialDelay: 500,
  maxDelay: 5000,
  backoffMultiplier: 2,
  jitter: 0.1,
  isRetryable: (error) => {
    const message = error.message.toLowerCase();
    return (
      message.includes('network') ||
      message.includes('timeout') ||
      message.includes('econnreset')
    );
  },
};
