/**
 * In-Memory Store
 *
 * In-memory implementations of MemoryStore and VectorStore.
 * For development and testing. Data does not persist across restarts.
 */

import type { MemoryEntry, MemoryStore, VectorStore } from '../types';

/**
 * In-memory implementation of MemoryStore.
 * Stores entries in a Map. Supports keyword-based search.
 */
export class InMemoryStore implements MemoryStore {
  private entries: Map<string, MemoryEntry> = new Map();

  async save(entry: MemoryEntry): Promise<void> {
    this.entries.set(entry.id, { ...entry });
  }

  async get(id: string): Promise<MemoryEntry | null> {
    return this.entries.get(id) ?? null;
  }

  async delete(id: string): Promise<void> {
    this.entries.delete(id);
  }

  async listByUser(
    userId: string,
    options?: { category?: MemoryEntry['category']; limit?: number },
  ): Promise<MemoryEntry[]> {
    let results = Array.from(this.entries.values()).filter(e => e.userId === userId);

    if (options?.category) {
      results = results.filter(e => e.category === options.category);
    }

    // Sort by most recently accessed
    results.sort((a, b) => b.lastAccessedAt - a.lastAccessedAt);

    if (options?.limit) {
      results = results.slice(0, options.limit);
    }

    return results;
  }

  async search(userId: string, query: string, limit: number = 10): Promise<MemoryEntry[]> {
    const queryLower = query.toLowerCase();
    const queryWords = queryLower.split(/\s+/).filter(w => w.length > 2);

    const scored = Array.from(this.entries.values())
      .filter(e => e.userId === userId)
      .map(entry => {
        const contentLower = entry.content.toLowerCase();
        let score = 0;

        // Exact substring match
        if (contentLower.includes(queryLower)) {
          score += 10;
        }

        // Word-level matches
        for (const word of queryWords) {
          if (contentLower.includes(word)) {
            score += 2;
          }
        }

        // Boost higher confidence entries
        score *= entry.confidence;

        // Slight recency boost
        const ageMs = Date.now() - entry.lastAccessedAt;
        const ageDays = ageMs / (1000 * 60 * 60 * 24);
        score *= Math.max(0.5, 1 - ageDays / 365); // Decay over a year

        return { entry, score };
      })
      .filter(({ score }) => score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);

    return scored.map(({ entry }) => entry);
  }

  /** Clear all entries (for testing) */
  clear(): void {
    this.entries.clear();
  }

  /** Get total entry count */
  get size(): number {
    return this.entries.size;
  }
}

/**
 * In-memory vector store using cosine similarity.
 * For development and testing only.
 */
export class InMemoryVectorStore implements VectorStore {
  private vectors: Map<string, { vector: number[]; metadata: Record<string, unknown> }> = new Map();

  async upsert(entries: Array<{
    id: string;
    vector: number[];
    metadata: Record<string, unknown>;
  }>): Promise<void> {
    for (const entry of entries) {
      this.vectors.set(entry.id, {
        vector: entry.vector,
        metadata: entry.metadata,
      });
    }
  }

  async query(
    vector: number[],
    topK: number,
    filter?: Record<string, unknown>,
  ): Promise<Array<{ id: string; score: number; metadata?: Record<string, unknown> }>> {
    const results: Array<{ id: string; score: number; metadata?: Record<string, unknown> }> = [];

    for (const [id, stored] of this.vectors) {
      // Apply filter if provided
      if (filter) {
        let matches = true;
        for (const [key, value] of Object.entries(filter)) {
          if (stored.metadata[key] !== value) {
            matches = false;
            break;
          }
        }
        if (!matches) continue;
      }

      const score = cosineSimilarity(vector, stored.vector);
      results.push({ id, score, metadata: stored.metadata });
    }

    return results
      .sort((a, b) => b.score - a.score)
      .slice(0, topK);
  }

  async delete(ids: string[]): Promise<void> {
    for (const id of ids) {
      this.vectors.delete(id);
    }
  }

  /** Clear all vectors (for testing) */
  clear(): void {
    this.vectors.clear();
  }

  /** Get total vector count */
  get size(): number {
    return this.vectors.size;
  }
}

/**
 * Compute cosine similarity between two vectors
 */
function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) return 0;

  let dotProduct = 0;
  let normA = 0;
  let normB = 0;

  for (let i = 0; i < a.length; i++) {
    dotProduct += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }

  const magnitude = Math.sqrt(normA) * Math.sqrt(normB);
  return magnitude === 0 ? 0 : dotProduct / magnitude;
}
