/**
 * Context Window Registry
 *
 * Maps model names to their context window sizes (in tokens).
 * Runtime-editable: apps can add/override models per project.
 */

import type { ContextWindowOptions } from './types';

/**
 * Default model context window sizes (tokens)
 */
const MODEL_CONTEXT_WINDOWS: Map<string, number> = new Map([
  // OpenAI
  ['gpt-4o', 128_000],
  ['gpt-4o-mini', 128_000],
  ['gpt-4-turbo', 128_000],
  ['gpt-4', 8_192],
  ['gpt-3.5-turbo', 16_385],
  ['gpt-5', 1_000_000],
  ['gpt-5-mini', 1_000_000],
  ['o1', 200_000],
  ['o1-mini', 128_000],
  ['o1-pro', 200_000],
  ['o3', 200_000],
  ['o3-mini', 200_000],
  ['o4-mini', 200_000],

  // Anthropic
  ['claude-3-opus', 200_000],
  ['claude-3-sonnet', 200_000],
  ['claude-3-haiku', 200_000],
  ['claude-3.5-sonnet', 200_000],
  ['claude-3.5-haiku', 200_000],
  ['claude-4-sonnet', 200_000],
  ['claude-4-opus', 200_000],

  // Google
  ['gemini-1.5-pro', 2_000_000],
  ['gemini-1.5-flash', 1_000_000],
  ['gemini-2.0-flash', 1_000_000],
  ['gemini-3-pro', 1_000_000],

  // xAI
  ['grok-2', 131_072],
  ['grok-3', 131_072],
  ['grok-4', 131_072],

  // Meta
  ['llama-3.1-8b', 128_000],
  ['llama-3.1-70b', 128_000],
  ['llama-3.1-405b', 128_000],
  ['llama-3.2', 128_000],
  ['llama-3.3', 128_000],
  ['llama-4', 128_000],

  // Mistral
  ['mistral-large', 128_000],
  ['mistral-small', 128_000],
  ['mixtral-8x7b', 32_768],

  // NVIDIA
  ['nemotron', 128_000],

  // DeepSeek
  ['deepseek-r1', 128_000],
  ['deepseek-v3', 128_000],

  // Qwen
  ['qwen-2.5', 128_000],
  ['qwen-3', 128_000],
]);

/** Default fallback context window size */
const DEFAULT_CONTEXT_WINDOW = 128_000;

/**
 * Register a single model's context window size.
 * Overwrites existing entries.
 *
 * @example
 * ```typescript
 * registerContextWindow('my-custom-model', 64_000);
 * ```
 */
export function registerContextWindow(model: string, tokens: number): void {
  MODEL_CONTEXT_WINDOWS.set(model.toLowerCase(), tokens);
}

/**
 * Register multiple model context windows at once.
 * Overwrites existing entries for matching models.
 *
 * @example
 * ```typescript
 * setContextWindows({
 *   'my-model': 64_000,
 *   'gpt-4o': 256_000, // override default
 * });
 * ```
 */
export function setContextWindows(windows: Record<string, number>): void {
  for (const [model, tokens] of Object.entries(windows)) {
    MODEL_CONTEXT_WINDOWS.set(model.toLowerCase(), tokens);
  }
}

/**
 * Get all registered context windows (for inspection/debugging)
 */
export function getContextWindows(): Record<string, number> {
  const result: Record<string, number> = {};
  for (const [model, tokens] of MODEL_CONTEXT_WINDOWS) {
    result[model] = tokens;
  }
  return result;
}

/**
 * Look up the context window size for a model.
 *
 * Uses fuzzy matching: "gpt-4o-2024-08-06" matches "gpt-4o".
 * Falls back to the default (128k) if no match is found.
 *
 * @param model - Model name (e.g., "gpt-4o", "claude-3.5-sonnet")
 * @param options - Override or default size options
 */
export function getContextWindow(model: string, options?: ContextWindowOptions): number {
  // Config override takes priority
  if (options?.override) {
    return options.override;
  }

  const normalized = model.toLowerCase();
  const defaultSize = options?.defaultSize ?? DEFAULT_CONTEXT_WINDOW;

  // Exact match
  if (MODEL_CONTEXT_WINDOWS.has(normalized)) {
    return MODEL_CONTEXT_WINDOWS.get(normalized)!;
  }

  // Fuzzy match: try progressively shorter prefixes
  // "gpt-4o-2024-08-06" → "gpt-4o-2024-08" → "gpt-4o-2024" → "gpt-4o"
  const parts = normalized.split('-');
  for (let len = parts.length - 1; len >= 1; len--) {
    const prefix = parts.slice(0, len).join('-');
    if (MODEL_CONTEXT_WINDOWS.has(prefix)) {
      return MODEL_CONTEXT_WINDOWS.get(prefix)!;
    }
  }

  // Try matching by checking if any registered model is a prefix of the input
  // Handles: "openai/gpt-4o" → match "gpt-4o", "nvidia/nemotron-xxx" → match "nemotron"
  for (const [registeredModel, tokens] of MODEL_CONTEXT_WINDOWS) {
    if (normalized.includes(registeredModel)) {
      return tokens;
    }
  }

  return defaultSize;
}
