/**
 * Tool Registry
 *
 * Manages tool registration, MCP integration, and provides
 * tools in API format for LLM calls.
 */

import type { Tool, ToolRegistry, ToolContext, APITool, MCPOptions, JSONSchema } from './types';

/**
 * MCP tool definition format
 */
interface MCPToolDef {
  name: string;
  description: string;
  parameters?: JSONSchema;
  inputSchema?: JSONSchema;
}

/**
 * Create a new tool registry
 */
export function createToolRegistry(): ToolRegistry {
  const tools: Map<string, Tool> = new Map();

  return {
    /**
     * Register a tool directly
     */
    register(tool: Tool): void {
      if (tools.has(tool.name)) {
        console.warn(`[ToolRegistry] Overwriting existing tool: ${tool.name}`);
      }
      tools.set(tool.name, tool);
    },

    /**
     * Register tools from an MCP server
     */
    async registerMCP(serverUrl: string, options?: MCPOptions): Promise<void> {
      try {
        // Fetch tool list from MCP server
        const response = await fetch(`${serverUrl}/tools`, {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
            ...options?.headers,
          },
          signal: options?.timeout
            ? AbortSignal.timeout(options.timeout)
            : undefined,
        });

        if (!response.ok) {
          throw new Error(`MCP server error: ${response.status}`);
        }

        const data = await response.json() as { tools?: MCPToolDef[] } | MCPToolDef[];
        const mcpTools: MCPToolDef[] = Array.isArray(data) ? data : (data.tools || []);

        // Register each tool with MCP execution wrapper
        for (const mcpTool of mcpTools) {
          const tool: Tool = {
            name: mcpTool.name,
            description: mcpTool.description,
            parameters: mcpTool.parameters || mcpTool.inputSchema || { type: 'object', properties: {} },
            execute: createMCPExecutor(serverUrl, mcpTool.name, options),
          };
          tools.set(tool.name, tool);
        }

        console.log(`[ToolRegistry] Registered ${mcpTools.length} tools from MCP server`);
      } catch (error) {
        console.error(`[ToolRegistry] Failed to register MCP tools:`, error);
        throw error;
      }
    },

    /**
     * List all registered tools
     */
    list(): Tool[] {
      return Array.from(tools.values());
    },

    /**
     * Get a tool by name
     */
    get(name: string): Tool | undefined {
      return tools.get(name);
    },

    /**
     * Execute a tool by name
     */
    async execute(
      name: string,
      args: Record<string, unknown>,
      context: ToolContext
    ): Promise<unknown> {
      const tool = tools.get(name);
      if (!tool) {
        throw new Error(`Tool not found: ${name}`);
      }
      return tool.execute(args, context);
    },

    /**
     * Get tools in API format (for LLM)
     */
    toAPIFormat(): APITool[] {
      return Array.from(tools.values()).map(tool => ({
        type: 'function',
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
      }));
    },
  };
}

/**
 * Create an executor function that calls MCP server
 */
function createMCPExecutor(
  serverUrl: string,
  toolName: string,
  options?: MCPOptions
): Tool['execute'] {
  return async (args: Record<string, unknown>, context: ToolContext) => {
    // Merge credentials with arguments if provided
    const payload: Record<string, unknown> = {
      tool: toolName,
      parameters: { ...args },
    };

    // Inject credentials for specific tools
    if (options?.credentials) {
      for (const [key, value] of Object.entries(options.credentials)) {
        payload[key] = value;
      }
    }

    const response = await fetch(`${serverUrl}/execute`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...options?.headers,
      },
      body: JSON.stringify(payload),
      signal: options?.timeout
        ? AbortSignal.timeout(options.timeout)
        : undefined,
    });

    if (!response.ok) {
      const errorBody = await response.text();
      throw new Error(`MCP tool execution failed: ${response.status} - ${errorBody}`);
    }

    const result = await response.json() as { result?: unknown };
    return result.result !== undefined ? result.result : result;
  };
}


